<?php declare(strict_types=1);$siteName=$content['site_name']??'VillaStay';$photo=static function(array $row):string{$v=(string)($row['cover_image']??'');return $v===''?'':(preg_match('~^https?://~i',$v)?$v:'/'.ltrim($v,'/'));}; ?><!doctype html><html lang="<?= e($locale??'tr') ?>"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Destinasyonlar · <?= e($siteName) ?></title><style>*{box-sizing:border-box}body{margin:0;font-family:Inter,system-ui,sans-serif;color:#20332c}.wrap{max-width:1180px;margin:35px auto;padding:0 18px}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:18px}.card{height:230px;position:relative;border-radius:18px;overflow:hidden}.card img{width:100%;height:100%;object-fit:cover}.card:after{content:"";position:absolute;inset:30% 0 0;background:linear-gradient(transparent,#0009)}.card strong{position:absolute;z-index:1;bottom:16px;left:16px;color:white;font-size:21px}.nav{display:flex;justify-content:space-between;align-items:center;margin-bottom:28px}.nav a{color:#167c80;font-weight:800}@media(max-width:800px){.grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:480px){.grid{gap:10px}.card{height:165px}.card strong{font-size:16px;left:11px;bottom:12px}}</style></head><body><main class="wrap"><div class="nav"><a href="/">← <?= e($siteName) ?></a><a href="/konaklamalar">Tüm konaklamalar →</a></div><h1>Popüler tatil destinasyonları</h1><p>Türkiye'nin farklı bölgelerinde keşfedilecek tatil rotaları.</p><div class="grid"><?php foreach($destinations as $d): ?><a class="card" href="/konaklamalar?<?= e(http_build_query(['city'=>$d['city']])) ?>"><?php if($photo($d)): ?><img src="<?= e($photo($d)) ?>" alt="<?= e($d['city']) ?>" loading="lazy"><?php endif; ?><strong><?= e($d['city']) ?> · <?= (int)$d['property_count'] ?> konaklama</strong></a><?php endforeach; ?></div></main></body></html>